function validate([operations, args]) {
  if (!Array.isArray(operations) || operations.length !== 2 || operations[0] !== 'Codec' || operations[1] !== 'encode') return 'Each case is [["Codec", "encode"], [[], [root]]]; the judge calls decode itself.';
  if (!Array.isArray(args) || args.length !== 2 || !Array.isArray(args[0]) || args[0].length !== 0 || !Array.isArray(args[1]) || args[1].length !== 1 || !Array.isArray(args[1][0])) return 'Pass the tree as the only argument of encode.';
  const root = args[1][0];
  if (root.length === 0) return null;
  if (root.some(v => v !== null && (!Number.isInteger(v) || v < 0 || v > 10000))) return 'Node values are whole numbers from 0 to 10^4.';
  if (root[0] === null) return 'A non-empty tree starts with the root value.';
  if (root.length > 1 && root[1] !== null) return 'The root value is followed by null, then its children.';
  if (root[root.length - 1] === null) return 'Drop the trailing nulls from the level order.';
  const depths = [1];
  let index = 2;
  for (let head = 0; index < root.length; head++) {
    if (head >= depths.length) return 'Every null starts the children of the next node; there are more groups than nodes.';
    while (index < root.length && root[index] !== null) {
      depths.push(depths[head] + 1);
      index++;
    }
    index++;
  }
  if (depths.length > 10000) return 'The tree has at most 10^4 nodes.';
  if (Math.max(...depths) > 1000) return 'The tree is at most 1000 levels tall.';
  return null;
}

