function adapt(input, solve, kit) {
  // LeetCode's N-ary node: a value and an ordered array of children.
  class Node {
    constructor(val = 0, children = []) {
      this.val = val;
      this.children = children;
    }
  }
  globalThis.Node = Node;
  globalThis._Node = Node;
  const values = input[1][1][0];
  const original = [];
  let root = null;
  if (values.length) {
    root = new Node(values[0], []);
    original.push(root);
    let index = 2;
    for (let head = 0; head < original.length && index < values.length; head++) {
      while (index < values.length && values[index] !== null) {
        const child = new Node(values[index], []);
        original[head].children.push(child);
        original.push(child);
        index++;
      }
      index++;
    }
  }
  const encoded = new solve().encode(root);
  if (encoded === undefined) throw new Error('encode did not return a value.');
  // Copy the binary tree into fresh TreeNodes so that only val, left and right reach decode.
  const isNode = value => value !== null && typeof value === 'object';
  if (encoded !== null && !isNode(encoded)) throw new Error('encode must return a TreeNode or null.');
  let copy = null;
  if (encoded !== null) {
    const seen = new Set();
    const limit = 4 * values.length + 2000;
    copy = new kit.TreeNode();
    const stack = [[encoded, copy]];
    while (stack.length) {
      const [from, to] = stack.pop();
      if (seen.has(from) || seen.size > limit) throw new Error('The binary tree from encode contains a cycle, a shared node, or too many nodes.');
      seen.add(from);
      if (!Number.isInteger(from.val)) throw new Error('Every binary tree node needs an integer val.');
      to.val = from.val;
      for (const side of ['left', 'right']) {
        const next = from[side] === undefined ? null : from[side];
        if (next === null) continue;
        if (!isNode(next)) throw new Error('left and right must be TreeNodes or null.');
        to[side] = new kit.TreeNode();
        stack.push([next, to[side]]);
      }
    }
  }
  const rebuilt = new solve().decode(copy);
  if (rebuilt === undefined) throw new Error('decode did not return a value.');
  if (rebuilt === null) return [];
  // Write the rebuilt tree in LeetCode's level order, checking that it is a fresh, finite tree.
  const used = new Set(original);
  const visited = new Set();
  const out = [rebuilt.val, null];
  const queue = [rebuilt];
  for (let head = 0; head < queue.length; head++) {
    const node = queue[head];
    if (!isNode(node)) throw new Error('Every child must be a node object.');
    if (used.has(node)) throw new Error('decode must build new nodes from the binary tree, not return the original ones.');
    if (visited.has(node) || queue.length > values.length + 2000) throw new Error('The rebuilt tree contains a cycle, a shared node, or too many nodes.');
    visited.add(node);
    const children = node.children == null ? [] : node.children;
    if (!Array.isArray(children)) throw new Error('children must be an array of nodes.');
    for (const child of children) {
      if (!isNode(child)) throw new Error('Every child must be a node object.');
      out.push(child.val === undefined ? null : child.val);
      queue.push(child);
    }
    out.push(null);
  }
  while (out.length && out[out.length - 1] === null) out.pop();
  return out;
}

