class Codec {
  encode(root) {
    if (root === null) {
      return null;
    }
    const node = new TreeNode(root.val);
    let previous = null;
    for (const child of root.children) {
      const encoded = this.encode(child);
      if (previous === null) {
        node.left = encoded;
      } else {
        previous.right = encoded;
      }
      previous = encoded;
    }
    return node;
  }

  decode(data) {
    if (data === null) {
      return null;
    }
    const node = new Node(data.val, []);
    let child = data.left;
    while (child !== null) {
      node.children.push(this.decode(child));
      child = child.right;
    }
    return node;
  }
}

