class Codec {
  // The mirror-image scheme, built with explicit stacks: right holds the first child, left the next sibling.
  encode(root) {
    if (!root) return null;
    const top = new TreeNode(root.val);
    const stack = [[root, top]];
    while (stack.length) {
      const [nary, binary] = stack.pop();
      let last = null;
      for (const child of nary.children) {
        const made = new TreeNode(child.val);
        if (last) last.left = made;
        else binary.right = made;
        last = made;
        stack.push([child, made]);
      }
    }
    return top;
  }

  decode(data) {
    if (!data) return null;
    const top = new Node(data.val, []);
    const stack = [[data, top]];
    while (stack.length) {
      const [binary, nary] = stack.pop();
      for (let link = binary.right; link; link = link.left) {
        const made = new Node(link.val, []);
        nary.children.push(made);
        stack.push([link, made]);
      }
    }
    return top;
  }
}

